sys_rte_eb_script_operation.script:
(function(batch, output) {
   for (var i = 0; i < batch.length; i++) {
      var input = batch[i].input; // Value of the input column.
      var matriculas = input.split(/[\n,]+/);
      var sysids = [];

      for (var ix = 0; ix < matriculas.length; ix++) {
        var mt = matriculas[ix].trim();
        if (!mt) continue;
        var gr = new GlideRecord('sys_user');
        gr.addQuery('employee_number', mt);
        gr.setLimit(1); gr.query();
        if (gr.next()) {
            sysids.push(gr.sys_id + '');
        } else {
            gs.warn('[TransformMap] sys_user nao encontrado para u_coordenadores: ' + mt);
        }
      }
      output[i] = sysids.join(',');
   }
})(batch, output);
